    std::vector<std::string> inputLines;
    std::string line;
    while (std::getline(std::cin, line)) {
        inputLines.push_back(line);
    }

    std::istringstream firstLineStream(inputLines[0]);
    int n;
    firstLineStream >> n;

    std::vector<int> x(n), y(n), r(n);
    for (int i = 0; i < n; ++i) {
        std::istringstream partsStream(inputLines[i + 1]);
        partsStream >> x[i] >> y[i] >> r[i];
    }

